void dotext(in vec2 uv, inout vec4 fragColor) {
    // background text
    vec4 textstuff2 = texture(iChannel2, uv - vec2(0.01, -0.01));
    float textDist2 = textstuff2.a;
    if (textstuff2.b > -textstuff2.g) {
        fragColor *= vec4(smoothstep(-0.01, 0.0, textDist2));
        fragColor += vec4(2.0 - 2.0 * smoothstep(0.0, 0.01, abs(textDist2)));
    }
    // main text
    vec4 textstuff = texture(iChannel2, uv);
    float textDist = textstuff.a;
    fragColor += vec4(2.0 - 2.0 * smoothstep(-0.01, 0.0, textDist));
    fragColor *= vec4(smoothstep(0.0, 0.01, abs(textDist)));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float asp = iResolution.x / iResolution.y;
    vec2 uv = fragCoord/iResolution.xy;
    vec2 ndc = uv * 2.0 - 1.0;
    float time = fract(iTime / 18.0) * 18.0;
    vec2 ndc2 = rotate2d(ndc, 3.1415926 / 2.0 * smoothstep(2.0, 4.0, time ));
    if (time < 6.0) {
        // rectangles
        fragColor = texture(iChannel0, ndc*0.5+0.5);
        fragColor *= texture(iChannel0, ndc2*0.5+0.5);
    } else if (time < 8.0) {
        ndc  = 0.8*rotate2d(fract((ndc *0.5+0.5)*5.0)*0.1-0.05-ndc , 3.1415926 / 2.0 * smoothstep(6.0, 8.0, time ));
        ndc2 = 0.8*rotate2d(fract((ndc2*0.5+0.5)*5.0)*0.1-0.05-ndc2, 3.1415926 / 2.0 * smoothstep(6.0, 8.0, time ));
        // plus pattern
        fragColor = vec4(int(texture(iChannel0, ndc*0.5+0.5).r) ^ 
                    int(texture(iChannel0, ndc2*0.5+0.5).r));
        // text
        if (time > 7.5) {
            dotext(uv, fragColor);
        }
    } else {
        // rings
        float dist = texture(iChannel1, uv).r;
        if ((int(time*2.0) & 1) == 0) {
            fragColor = vec4(step(fract(dist * 4.0), 0.4));
        } else {
            float dq = floor(fract(dist*5.0)*8.0)/8.0;
            fragColor = vec4(rwgb(dq-0.05), 1.0);
        }
        float e0 = fract(-uv.y + uv.x*0.09 + iTime * 2.0) * 2.0;
        float e1 = fract(-uv.y + uv.x*0.07 + iTime * 2.0) * 2.0;
        // spiral
        float d = length(ndc2 * vec2(1.0, asp)); 
        if (d < (time - 10.0)*0.25) {
            fragColor = (1.0 + (time-10.0)*0.125) / (1.0 + d*d) * vec4(0.8, 0.4, 0.0, 1.0);
            fragColor *= spiral(ndc2 * vec2(-1.0, asp), iTime*0.5);
        }
        // text
        if (time > 17.5) {
            dotext(uv, fragColor);
        }

        fragColor += smoothstep(0.3, 0.35, e0) * (1.0 - smoothstep(0.8, 0.85, e1)) * 0.2;
    }
    // horizontal detail lines
    fragColor *= float((int(fragCoord.y) & 2) == 0) * 0.2 + 0.8;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord/iResolution.xy;
    vec2 ndc = uv * 2.0 - 1.0;
    ndc.x = 1.0 - sqrt(1.0 - (ndc.x*ndc.x) ) ;
    ndc = rotate2d(ndc.xy, 3.1415926 / 4.0);
    float manhattan1 = abs(ndc.x) + abs(ndc.y);
    manhattan1 = pow(manhattan1, 0.125) ;
    float time = iTime*0.2 + floor(iTime*2.0)*0.01;
    float squares1 = fract(20.0 * (manhattan1 - time) );
    float time8 = fract(iTime / 8.0) * 8.0;
    fragColor = vec4(vec3( step(squares1 * 1.414 - 0.414 * smoothstep(6.0, 8.0, time8), 0.5) ), 1.0);
}

const highp float PHI1 = 1.0 - 1.0 / float(1.61803398);
const highp vec2  PHI2 = 1.0 - 1.0 / pow(vec2(1.32471795), vec2(1.0, 2.0));

float r21(in int v) {
    return fract(PHI1 * float(v));
}
vec2 r22(in int v) {
    return fract(PHI2 * float(v));
}

vec2 rotate2d(in vec2 v, in float a) {
    float sinA = sin(a);
    float cosA = cos(a);
    return vec2(v.x * cosA - v.y * sinA, v.y * cosA + v.x * sinA);	
}

// thanks Jerome_ https://www.shadertoy.com/view/WtjSWt
float spiral(in vec2 ndc, in float iTime) {
    float angle = atan(ndc.y, ndc.x) / (3.1415926 * 2.0);
    float offset = sqrt(dot(ndc, ndc))+angle*0.25;
    float circles = mod(offset-iTime,0.25);
    return step(circles-0.1,0.1) - step(circles,0.1);
}

vec3 rwgb(in float t) {
    vec3 r = vec3(1.0,0.0,0.0);
    vec3 w = vec3(1.0,1.0,1.0);
    vec3 g = vec3(0.0,1.0,0.0);
    vec3 b = vec3(0.0,0.0,0.0);
    float out_r = 1.0 - smoothstep(0.0, 0.5, t) + smoothstep(0.75, 1.0, t);
    float out_g = smoothstep(0.0, 0.25, t) * (1.0 - smoothstep(0.0, 0.75, t));
    float out_b = smoothstep(0.0, 0.25, t) * (1.0 - smoothstep(0.0, 0.5, t));
    out_r *= step(t,0.31) + step(0.34,t);
    out_g *= step(t,0.31) + step(0.34,t);
    out_b *= 0.5 + step(t,0.31) + step(0.34,t);
    out_r += 0.5 * step(0.3,t) * step(t,0.35); // yellow stripe
    out_g += 0.4 * step(0.3,t) * step(t,0.35);
    return clamp(vec3(out_r, out_g, out_b) * 2.0, 0.0, 1.0) * 0.8;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord/iResolution.xy;
    vec2 ndc = uv * 2.0 - 1.0;
    ndc.x *= iResolution.x/iResolution.y;
    float time = iTime*0.2 + floor(iTime*2.0)*0.05;
    float dist = pow(dot(ndc, ndc), 0.125)-time;
    fragColor = vec4(dist);
}

